           JOIN pg_catalog.pg_rewrite r ON d.classid='pg_catalog.pg_rewrite'::regclass AND r.oid=d.objid
           JOIN pg_catalog.pg_class c ON c.oid=r.ev_class
           WHERE d.refobjid=ANY(tables) AND c.relkind IN ('v','m')) THEN
